       private boolean seenOuterMostDocIterator = false;

       @Override
       public NamedList readNamedList(DataInputInputStream dis) throws IOException {
         int sz = readSize(dis);
         NamedList nl = new NamedList();
         if (namedList[0] == null) {
           namedList[0] = nl;
         }
         for (int i = 0; i < sz; i++) {
